import{_ as i,l as o,o as t,c as l,v as e,p as n,x as s,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"Dijkstra 在 OSPF","description":"","frontmatter":{"title":"Dijkstra 在 OSPF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ospf-dijkstra.md","filePath":"cs/ospf-dijkstra.md","lastUpdated":1789023840000}'),h={name:"cs/ospf-dijkstra.md"};function B(P,a,_,S,k,f){const r=o("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="dijkstra-在-ospf" tabindex="-1">Dijkstra 在 OSPF <a class="header-anchor" href="#dijkstra-在-ospf" aria-label="Permalink to &quot;Dijkstra 在 OSPF&quot;">​</a></h1><div class="epigraph"><p>链路状态库是同一张带权图；每台路由器以自己为源跑 Dijkstra，下一跳才写进 FIB。</p><footer>—— 据 Dijkstra 最短路；Moy, RFC 2328 OSPF Version 2；Kurose and Ross</footer></div><p><a href="/cs/link-state">上一课</a>给出洪泛邻接与「各节点独立计算」。本课不重写 LSA 洪泛可靠性。缺口是计算本身：图课的 <a href="/cs/dijkstra">Dijkstra</a> 已经会单源最短路；这里要接到 OSPF 的代价、区域直觉和「下一跳是邻居而不是整条路径」。本课不把 BGP 政策提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链路状态通告描述「我连谁、代价多少」。若只停在「有一张图」，还不会转发。OSPF：从 LSDB 建图，节点是路由器与网络，边权是接口代价。以本机为源跑 Dijkstra，得到到每个前缀的出口邻居。区域把洪泛范围切开，骨干连通各区域，避免全网一张图过大。缺口是<strong>把最短路树写成转发表</strong>。</p><p><span class="marginnote">代价常与带宽相关，由管理设定，不是时延测量。ECMP 在多条等代价时分流，仍要求下一跳是邻居。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>同步 LSDB（可靠洪泛、序号）。算 SPF 树。把叶子网络的前缀安装为「下一跳 = 树上来的第一跳邻居」，再交给 <a href="/cs/lpm">LPM</a>。区域内与区域间前缀来源不同，但查找规则仍是最长前缀。本课不把全部 LSA 类型表当必背。</p>',8)),(t(),n(c,null,{default:s(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LSDB%5B%22%E9%93%BE%E8%B7%AF%E7%8A%B6%E6%80%81%E5%BA%93%22%5D%20--%3E%20G%5B%22%E5%B8%A6%E6%9D%83%E5%9B%BE%22%5D%0A%20%20G%20--%3E%20SPF%5B%22%E6%9C%AC%E6%9C%BA%E4%B8%BA%E6%BA%90%E7%9A%84%20Dijkstra%22%5D%0A%20%20SPF%20--%3E%20FIB%5B%22%E4%B8%8B%E4%B8%80%E8%B7%B3%E5%86%99%E5%85%A5%20FIB%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每台路由器计算自己的树，但仍应得到相容的转发：同一张无向代价图、同一算法。与距离向量对照：坏消息随拓扑洪泛，不必数到无穷。域内 IGP 仍是一个管理域的最短路；跨域政策不是代价最小，下一课 BGP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IS-IS TLV 细节当第二条主干，不把流量工程的约束最短路写成 OSPF 正文。多区域虚拟链路是例外，不展开。自治系统之间如何交换路径，下一课 BGP 直觉。</p><p>后课默认：一个 AS 内部可以用 Dijkstra 填下一跳。互联网的边界路由换政策语言。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OSPF 在同步图上跑 Dijkstra，安装邻居下一跳。</li><li>区域缩小洪泛，不改变 LPM。</li><li>跨 AS 不是最短路，下一课 BGP。</li><li>出处：RFC 2328；Dijkstra；Kurose and Ross。</li></ul>',7))])}const D=i(h,[["render",B]]);export{m as __pageData,D as default};
